package api_test

import (
	"fmt"
	"net/http"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// storeInvoice adds invoice i to the store directly, with a status and subscription that vary with i.
func storeInvoice(t testing.TB, s *store.Store, orgID, customerID string, i int, at time.Time) {
	t.Helper()
	inv := store.Invoice{OrgID: orgID, CustomerID: customerID, Currency: money.USD, Lines: []store.Line{{Description: fmt.Sprintf("Seat %d", i), Quantity: 2, UnitAmount: 1500}}}
	if i%4 == 0 {
		inv.SubscriptionID = fmt.Sprintf("sub_%d", i%300)
	}
	created, err := s.CreateInvoice(inv, at)
	if err != nil {
		t.Fatal(err)
	}
	if i%3 == 0 || i%10 == 1 {
		status := store.InvoicePaid
		if i%10 == 1 {
			status = store.InvoiceVoid
		}
		if _, err := s.UpdateInvoice(orgID, created.ID, func(inv *store.Invoice) error { inv.Status = status; return nil }); err != nil {
			t.Fatal(err)
		}
	}
}

func TestListInvoicesLargeOrganizationIsFast(t *testing.T) {
	if testing.Short() {
		t.Skip("builds 60,000 invoices")
	}
	e := apitest.New(t)
	start := e.Clock.Now()
	customers := make([]store.Customer, 5000)
	for i := range customers {
		c, err := e.Store.CreateCustomer(e.Acme.ID, fmt.Sprintf("Customer %d", i), fmt.Sprintf("customer%d@acme.example", i), start)
		if err != nil {
			t.Fatal(err)
		}
		customers[i] = c
	}
	globex, err := e.Store.CreateCustomer(e.Globex.ID, "Other", "other@globex.example", start)
	if err != nil {
		t.Fatal(err)
	}
	for i := range 60000 {
		storeInvoice(t, e.Store, e.Acme.ID, customers[i%len(customers)].ID, i, start.Add(time.Duration(i)*time.Second))
		if i%30 == 0 {
			storeInvoice(t, e.Store, e.Globex.ID, globex.ID, i, start.Add(time.Duration(i)*time.Second))
		}
	}

	queries := []string{
		"",
		"?customer_id=" + customers[7].ID,
		"?subscription_id=sub_7",
		"?status=paid",
		"?status=void",
		"?status=open&customer_id=" + customers[7].ID,
	}
	for _, q := range queries {
		first, took := timedGet(t, e, "/v1/invoices?"+q[min(1, len(q)):])
		if first.Code != http.StatusOK {
			t.Fatalf("%q: %s", q, first)
		}
		if len(first.Map(t)["items"].([]any)) == 0 && q != "?status=void" {
			t.Fatalf("%q: no items", q)
		}
		t.Logf("%q first page: %v", q, took)
		if took > 250*time.Millisecond {
			t.Errorf("%q first page took %v, want under 250ms", q, took)
		}
		next, _ := first.Map(t)["next_cursor"].(string)
		if next == "" {
			continue
		}
		second, took := timedGet(t, e, "/v1/invoices?"+q[min(1, len(q)):]+"&cursor="+next)
		if second.Code != http.StatusOK {
			t.Fatalf("%q second page: %s", q, second)
		}
		t.Logf("%q second page: %v", q, took)
		if took > 250*time.Millisecond {
			t.Errorf("%q second page took %v, want under 250ms", q, took)
		}
	}
}

// timedGet answers a GET for the Acme owner and how long the request took.
func timedGet(t testing.TB, e *apitest.Env, path string) (*apitest.Response, time.Duration) {
	t.Helper()
	began := time.Now()
	r := e.Do("GET", path, e.Acme.Key, nil)
	return r, time.Since(began)
}

