// InvoicePosition is where an invoice sorts among an organization's invoices: by creation time, then by ID.
type InvoicePosition struct {
	CreatedAt time.Time
	ID        string
}

// matches reports whether inv has every field f asks for.
func (f InvoiceFilter) matches(inv Invoice) bool {
	return (f.CustomerID == "" || inv.CustomerID == f.CustomerID) &&
		(f.SubscriptionID == "" || inv.SubscriptionID == f.SubscriptionID) &&
		(f.Status == "" || inv.Status == f.Status)
}

// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Invoice{}
	for _, id := range s.invoicesByOrg[orgID] {
		if inv := s.invoices[id]; f.matches(inv) {
			out = append(out, copyInvoice(inv))
		}
	}
	return out
}

// ListInvoicePage returns up to limit of an organization's invoices that match f and sort after `after` (the first page when
// it is nil), oldest first (ties by ID). more reports whether a matching invoice sorts after the page.
func (s *Store) ListInvoicePage(orgID string, f InvoiceFilter, after *InvoicePosition, limit int) (page []Invoice, more bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	ids := s.invoicesByOrg[orgID]
	start := 0
	if after != nil {
		start = sort.Search(len(ids), func(i int) bool { return invoiceBefore(after.CreatedAt, after.ID, s.invoices[ids[i]]) })
	}
	page = []Invoice{}
	for _, id := range ids[start:] {
		inv := s.invoices[id]
		if !f.matches(inv) {
			continue
		}
		if len(page) == limit {
			return page, true
		}
		page = append(page, copyInvoice(inv))
	}
	return page, false
}

// invoiceBefore reports whether an invoice created at t with the ID id sorts before inv.
func invoiceBefore(t time.Time, id string, inv Invoice) bool {
	if !t.Equal(inv.CreatedAt) {
		return t.Before(inv.CreatedAt)
	}
	return id < inv.ID
}

// indexInvoice adds inv, which is stored, to its organization's list of invoices. The caller holds the lock.
func (s *Store) indexInvoice(inv Invoice) {
	ids := s.invoicesByOrg[inv.OrgID]
	i := sort.Search(len(ids), func(i int) bool { return invoiceBefore(inv.CreatedAt, inv.ID, s.invoices[ids[i]]) })
	ids = append(ids, "")
	copy(ids[i+1:], ids[i:])
	ids[i] = inv.ID
	s.invoicesByOrg[inv.OrgID] = ids
}

// sortInvoiceIndex puts every organization's invoice list in order. It runs once after a snapshot is loaded.
func (s *Store) sortInvoiceIndex() {
	for _, ids := range s.invoicesByOrg {
		sort.Slice(ids, func(i, j int) bool {
			a, b := s.invoices[ids[i]], s.invoices[ids[j]]
			return invoiceBefore(a.CreatedAt, a.ID, b)
		})
	}
}

