// walkInvoices follows next_cursor from cursor ("" for the first page) and returns every invoice ID listed.
func walkInvoices(t testing.TB, e *apitest.Env, query string, limit int, cursor string) []string {
	t.Helper()
	out := []string{}
	for {
		path := fmt.Sprintf("/v1/invoices?%s&limit=%d", query, limit)
		if cursor != "" {
			path += "&cursor=" + cursor
