func TestListInvoicesPagesWalkEveryFilter(t *testing.T) {
	e := apitest.New(t)
	jane := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	joe := e.CreateCustomer(e.Acme, "Joe", "joe@example.com")
	globex := e.CreateCustomer(e.Globex, "Other", "other@example.com")

	// created is Acme's invoices, oldest first: the clock stands still for groups of invoices, so ties sort by ID.
	var created []string
	for i := range 12 {
		if i%4 == 0 {
			e.Clock.Advance(time.Minute)
		}
		customer := jane
		if i%3 == 0 {
			customer = joe
		}
		var inv store.Invoice
		e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{
			"customer_id": customer.ID, "currency": "USD", "lines": []map[string]any{{"description": fmt.Sprintf("Item %d", i), "quantity": 1, "unit_amount": 1000 + i}},
		}, &inv)
		created = append(created, inv.ID)
	}
	for range 4 {
		inv, err := e.Store.CreateInvoice(store.Invoice{OrgID: e.Acme.ID, CustomerID: jane.ID, SubscriptionID: "sub_1", Currency: money.USD, Lines: []store.Line{{Description: "Seat", Quantity: 1, UnitAmount: 500}}}, e.Clock.Now())
		if err != nil {
			t.Fatal(err)
		}
		created = append(created, inv.ID)
	}
	if _, err := e.Store.CreateInvoice(store.Invoice{OrgID: e.Globex.ID, CustomerID: globex.ID, Currency: money.USD, Lines: []store.Line{{Description: "Other", Quantity: 1, UnitAmount: 500}}}, e.Clock.Now()); err != nil {
		t.Fatal(err)
	}
	for _, i := range []int{2, 6, 13} {
		if _, err := e.Store.UpdateInvoice(e.Acme.ID, created[i], func(inv *store.Invoice) error { inv.Status = store.InvoicePaid; return nil }); err != nil {
			t.Fatal(err)
		}
	}
	for _, i := range []int{5, 9} {
		e.MustDo(http.StatusOK, "POST", "/v1/invoices/"+created[i]+"/void", e.Acme.Key, nil, nil)
	}

	filters := []struct {
		query string
		keep  func(store.Invoice) bool
	}{
		{"", func(store.Invoice) bool { return true }},
		{"customer_id=" + joe.ID, func(inv store.Invoice) bool { return inv.CustomerID == joe.ID }},
		{"customer_id=" + jane.ID + "&status=open", func(inv store.Invoice) bool { return inv.CustomerID == jane.ID && inv.Status == store.InvoiceOpen }},
		{"subscription_id=sub_1", func(inv store.Invoice) bool { return inv.SubscriptionID == "sub_1" }},
		{"status=paid", func(inv store.Invoice) bool { return inv.Status == store.InvoicePaid }},
		{"status=void&subscription_id=sub_1", func(inv store.Invoice) bool { return inv.Status == store.InvoiceVoid && inv.SubscriptionID == "sub_1" }},
	}
	for _, f := range filters {
		var want []string
		for _, id := range created {
			if inv, _ := e.Store.Invoice(e.Acme.ID, id); f.keep(inv) {
				want = append(want, id)
			}
		}
		if len(want) == 0 {
			t.Fatalf("%q matches nothing; the fixture is wrong", f.query)
		}
		for _, limit := range []int{1, 3, 100} {
			if got := walkInvoices(t, e, f.query, limit, ""); !slices.Equal(got, want) {
				t.Fatalf("%q with limit %d listed %v, want %v", f.query, limit, got, want)
			}
		}
	}

	// A new invoice made between two pages sorts after the cursor, so it is listed last and nothing is repeated or skipped.
	var first listedIDs
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?limit=3", e.Acme.Key, nil, &first)
	var added store.Invoice
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{
		"customer_id": jane.ID, "currency": "USD", "lines": []map[string]any{{"description": "Late", "quantity": 1, "unit_amount": 900}},
	}, &added)
	got := append(first.ids(), walkInvoices(t, e, "", 3, first.NextCursor)...)
	if want := append(created, added.ID); !slices.Equal(got, want) {
		t.Fatalf("walk across a new invoice listed %v, want %v", got, want)
	}

	for _, tc := range []struct{ path, code string }{
		{"/v1/invoices?status=bogus", "invalid_status"},
		{"/v1/invoices?limit=0", "invalid_limit"},
		{"/v1/invoices?cursor=%21%21", "invalid_cursor"},
	} {
		if r := e.Do("GET", tc.path, e.Acme.Key, nil); r.Code != http.StatusBadRequest || r.Map(t)["error"] != tc.code {
			t.Fatalf("%s: %s", tc.path, r)
		}
	}
}

