func TestListInvoicesPagesWalkEveryFilter(t *testing.T) {
	e := apitest.New(t)
	jane := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	joe := e.CreateCustomer(e.Acme, "Joe", "joe@example.com")
	globex := e.CreateCustomer(e.Globex, "Other", "other@example.com")

	// created is Acme's invoices, oldest first: the clock stands still for groups of invoices, so ties sort by ID.
	var created []string
	for i := range 12 {
		if i%4 == 0 {
			e.Clock.Advance(time.Minute)
		}
		customer := jane
		if i%3 == 0 {
			customer = joe
		}
		var inv store.Invoice
		e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{
			"customer_id": customer.ID, "currency": "USD", "lines": []map[string]any{{"description": fmt.Sprintf("Item %d", i), "quantity": 1, "unit_amount": 1000 + i}},
		}, &inv)
		created = append(created, inv.ID)
	}
	for range 4 {
		inv, err := e.Store.CreateInvoice(store.Invoice{OrgID: e.Acme.ID, CustomerID: jane.ID, SubscriptionID: "sub_1", Currency: money.USD, Lines: []store.Line{{Description: "Seat", Quantity: 1, UnitAmount: 500}}}, e.Clock.Now())
		if err != nil {
