		{"/v1/invoices?status=bogus", "invalid_status"},
		{"/v1/invoices?limit=0", "invalid_limit"},
		{"/v1/invoices?cursor=%21%21", "invalid_cursor"},
	} {
		if r := e.Do("GET", tc.path, e.Acme.Key, nil); r.Code != http.StatusBadRequest || r.Map(t)["error"] != tc.code {
