func TestListInvoicePageOrdersAndPages(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	b := newOrg(t, s, "B")
	c, _ := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	cb, _ := s.CreateCustomer(b.ID, "Bo", "bo@example.com", t0)
	create := func(orgID, customerID string, at time.Time) Invoice {
		t.Helper()
		inv, err := s.CreateInvoice(Invoice{OrgID: orgID, CustomerID: customerID, Currency: money.EUR, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 100}}}, at)
		if err != nil {
			t.Fatal(err)
		}
		return inv
	}
	// Created out of time order, with two invoices at the same time: the list sorts by time, then ID.
	late := create(a.ID, c.ID, t0.Add(time.Hour))
	early := create(a.ID, c.ID, t0)
	tie1 := create(a.ID, c.ID, t0.Add(time.Minute))
	tie2 := create(a.ID, c.ID, t0.Add(time.Minute))
	create(b.ID, cb.ID, t0.Add(time.Minute))
	want := []string{early.ID, tie1.ID, tie2.ID, late.ID}
	ids := func(invs []Invoice) []string {
		out := []string{}
		for _, inv := range invs {
			out = append(out, inv.ID)
		}
		return out
	}
	if got := ids(s.ListInvoices(a.ID, InvoiceFilter{})); !slices.Equal(got, want) {
		t.Fatalf("ListInvoices = %v, want %v", got, want)
	}

	page, more := s.ListInvoicePage(a.ID, InvoiceFilter{}, nil, 2)
	if got := ids(page); !slices.Equal(got, want[:2]) || !more {
		t.Fatalf("first page = %v, more %v", got, more)
	}
	page, more = s.ListInvoicePage(a.ID, InvoiceFilter{}, &InvoicePosition{CreatedAt: tie1.CreatedAt, ID: tie1.ID}, 2)
	if got := ids(page); !slices.Equal(got, want[2:]) || more {
		t.Fatalf("page after %s = %v, more %v", tie1.ID, got, more)
	}
	page, more = s.ListInvoicePage(a.ID, InvoiceFilter{}, &InvoicePosition{CreatedAt: late.CreatedAt, ID: late.ID}, 2)
	if len(page) != 0 || more {
		t.Fatalf("page after the last invoice = %v, more %v", ids(page), more)
	}

	// A new invoice at the same time as the cursor's invoice, with a greater ID, sorts after it.
	tie3 := create(a.ID, c.ID, t0.Add(time.Minute))
	page, _ = s.ListInvoicePage(a.ID, InvoiceFilter{}, &InvoicePosition{CreatedAt: tie1.CreatedAt, ID: tie2.ID}, 10)
	if got := ids(page); !slices.Equal(got, []string{tie3.ID, late.ID}) {
		t.Fatalf("page after %s = %v", tie2.ID, got)
	}

	// Filters apply within the page walk, and the walk sees only the organization's invoices.
	if _, err := s.UpdateInvoice(a.ID, tie2.ID, func(i *Invoice) error { i.Status = InvoicePaid; return nil }); err != nil {
		t.Fatal(err)
	}
	page, more = s.ListInvoicePage(a.ID, InvoiceFilter{Status: InvoicePaid}, nil, 1)
	if got := ids(page); !slices.Equal(got, []string{tie2.ID}) || more {
		t.Fatalf("paid invoices = %v, more %v", got, more)
	}
	if page, more = s.ListInvoicePage(a.ID, InvoiceFilter{CustomerID: cb.ID}, nil, 1); len(page) != 0 || more {
		t.Fatalf("another organization's customer = %v, more %v", ids(page), more)
	}

	// A loaded snapshot lists its invoices in the same order.
	restored, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if got := ids(restored.ListInvoices(a.ID, InvoiceFilter{})); !slices.Equal(got, []string{early.ID, tie1.ID, tie2.ID, tie3.ID, late.ID}) {
		t.Fatalf("restored ListInvoices = %v", got)
	}
}
